.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1i (his #50, from the lint of the craft shot): A LOCKED TILE KEEPS ITS NAME. A recipe you cannot make
   yet (and a locked tile anywhere in the shop) faded the whole tile to 42 percent, so its name read at about 2.3:1 against the
   cell. The picture and the price fade as before; the name stays readable in the second text colour, as on the locked Fashion
   tiles (ui6b), and a pad highlight on it no longer fades it twice. */
#root .vcell.locked, #root .vcell.locked.padfocus{ opacity:1 !important; border-color:var(--ui-line); }
#root .vcell.locked > *:not(.vlbl){ opacity:.42; }
#root .vcell.locked .vlbl{ opacity:1; color:var(--tx-2); }

check:
{v:'VER',what:'his #50 (UI redesign ui5q1i, from the lint of the craft shot): on the craft tab a tile you cannot make yet keeps its name at full strength (no fade on the name or the tile) and still dims its picture',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], el, lb, pic, o;
   function opac(e){ var v=1; for(var p=e;p&&p.nodeType===1;p=p.parentElement){ v*=parseFloat(getComputedStyle(p).opacity); } return v; }
   try{
     __topClear(); __hubEnter(); __station('trader','KeyR');
     el=document.querySelector('#craftgrid .vcell.locked');
     if(!el) return 'SKIP: no recipe on the craft tab is out of reach here';
     lb=el.querySelector('.vlbl');
     if(!lb) bad.push('control: a locked craft tile has no name');
     else { o=opac(lb); if(o<0.99) bad.push('a locked craft tile fades its name to '+o.toFixed(2)); }
     pic=[].filter.call(el.children,function(c){ return !c.classList.contains('vlbl'); })[0];
     if(pic&&opac(pic)>0.9) bad.push('a locked craft tile no longer dims its picture');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
